import{_ as d,o as e,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovCircleW 整圆摆动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovCircleW.md","filePath":"3. 指令/1. 运动指令/MovCircleW.md","lastUpdated":1778862643000}'),a={name:"3. 指令/1. 运动指令/MovCircleW.md"};function r(o,t,n,l,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="movcirclew-整圆摆动" tabindex="-1">MovCircleW 整圆摆动 <a class="header-anchor" href="#movcirclew-整圆摆动" aria-label="Permalink to &quot;MovCircleW 整圆摆动&quot;">​</a></h1><p>整圆摆动指令（MovCircleW）用于使机器人在执行整圆运动的过程中，保持持续的摆弧运动。该指令结合了整圆插补与摆动控制，目前主要支持<strong>正弦摆</strong>和<strong>三角摆</strong>两种运动模式，常用于环形焊缝的焊接。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovCircleW(A, P, [V], [B], [C], [Tool], [Coord], [PayLoad], WEAVE, [O], [DO])</p><p>MovCircleW(中间点, 目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 摆动参数, [姿态控制], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>A</td><td>APOS 或 CPOS 变量</td><td>整圆路径上的第一个辅助点，用于与起点、辅助点 2 共同确定圆的直径和空间位置。该点的姿态不影响最终轨迹。</td><td>必填</td></tr><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>整圆路径上的第二个辅助点。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人沿整圆轨迹运动的速度。SPEED 变量中的 <code>tcp</code>（平移）和 <code>ori</code>（旋转）分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点（回到起点）时的过渡方式。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡数值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / 变位机变量</td><td>执行轨迹时使用的用户坐标系或变位机坐标系。</td><td>可选，默认使用当前系统设置</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>WEAVE</td><td>WEAVE 变量</td><td>定义摆动动作的核心参数，包括：<strong>摆频</strong>（每秒摆动的周期数）、<strong>摆幅</strong>（偏离中心轨迹的宽度）、<strong>停止时间</strong>（在摆动两侧端点的驻留时间）、<strong>旋转</strong>（摆动过程中的姿态变化）。</td><td>必填</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：受全局速度倍率影响（默认）。<br><code>GOVROFF</code>：不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作。目前支持：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovCircleW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, WV1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DO1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人将按照 <strong>WV1</strong> 设定的摆动样式，经过 <strong>P1</strong> 点向 <strong>P2</strong> 点进行圆弧摆动运动，常用于圆弧焊缝的填充。</p>',13)])])}const E=d(a,[["render",r]]);export{k as __pageData,E as default};
